-- V2.5: archive, KPI alerts and rankings
ALTER TABLE students MODIFY status ENUM('active','inactive','archived') NOT NULL DEFAULT 'active', ADD COLUMN archived_at DATETIME NULL AFTER status, ADD COLUMN archived_by BIGINT UNSIGNED NULL AFTER archived_at, ADD COLUMN archive_reason VARCHAR(255) NULL AFTER archived_by, ADD INDEX idx_students_group_status(group_id,status);
CREATE TABLE IF NOT EXISTS exam_scores(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,exam_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,score DECIMAL(8,2) NOT NULL,UNIQUE(exam_id,student_id),FOREIGN KEY(exam_id) REFERENCES exams(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id),INDEX(student_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS homework_results(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,assigned_date DATE NOT NULL,status ENUM('complete','incomplete','excused') NOT NULL,notes VARCHAR(255) NULL,FOREIGN KEY(student_id) REFERENCES students(id),INDEX(student_id,assigned_date,status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS recitation_results(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,recitation_date DATE NOT NULL,errors_count INT UNSIGNED NOT NULL DEFAULT 0,notes VARCHAR(255) NULL,FOREIGN KEY(student_id) REFERENCES students(id),INDEX(student_id,recitation_date)) ENGINE=InnoDB;
